// Generated by OrchestKit Claude Plugin
// Created: 2026-08-21

// Markdown twins for the named, non-/docs pages an agent is most likely to
// probe by name: /developers.md and /yonyon.md.
//
// The docs have always told agents "append .md to a page URL". That was only
// ever true under /docs, /developers.md returned the HTML not-found page, so an
// agent following our own instruction to find "yonyon developer resources" got
// markup instead of content. These twins make the documented convention true
// for the two pages that answer a name-based query, and they render from the
// SAME data the HTML pages render from (lib/developer-resources.ts,
// lib/yonyon-faqs.ts) so the two representations cannot drift.

import { COUNTS, SITE } from "@/lib/constants";
import { withFrontmatter } from "@/lib/md-frontmatter";
import { DEVELOPER_RESOURCES } from "@/lib/developer-resources";
import { YONYON_FAQS } from "@/lib/yonyon-faqs";

/** Slugs with a Markdown twin. Kept in sync with app/(home)/* by a unit test. */
export const MARKDOWN_TWIN_SLUGS = ["developers", "yonyon"] as const;
export type MarkdownTwinSlug = (typeof MARKDOWN_TWIN_SLUGS)[number];

export function hasMarkdownTwin(slug: string): slug is MarkdownTwinSlug {
	return (MARKDOWN_TWIN_SLUGS as readonly string[]).includes(slug);
}

function absolute(href: string): string {
	return href.startsWith("http") ? href : `${SITE.domain}${href}`;
}

const DEVELOPERS_TITLE = `${SITE.name} by Yonyon: developer resources`;
const DEVELOPERS_LEAD = `Every developer-facing surface of ${SITE.name}, the free MIT-licensed Claude Code plugin published by the Yonyon software studio. All public, all free, no account required.`;

function developersMarkdown(): string {
	return [
		`# ${DEVELOPERS_TITLE}`,
		"",
		`> ${DEVELOPERS_LEAD}`,
		"",
		"## Resources",
		"",
		...DEVELOPER_RESOURCES.map((r) => `- [${r.title}](${absolute(r.href)}): ${r.desc}`),
		"",
		"## For AI agents",
		"",
		`- Start at the RFC 9727 API catalog (${SITE.domain}/.well-known/api-catalog) or ${SITE.domain}/llms.txt.`,
		"- No credentials are required. Errors use the RFC 9457 Problem Details shape.",
		"- Every API response carries the IETF `RateLimit-*` headers; a `429` also carries `Retry-After`.",
		`- Versioning and deprecation guarantees: ${SITE.domain}/api-policy (Markdown twin: ${SITE.domain}/api-policy.md).`,
		"- Append `.md` to any documentation page URL, or send `Accept: text/markdown`, for raw Markdown.",
		"",
		"## Publisher",
		"",
		`Yonyon is an independent software studio building developer tooling for AI-assisted engineering; ${SITE.name} is its flagship product (${COUNTS.skills} skills, ${COUNTS.agents} agents, ${COUNTS.hooks} lifecycle hooks). It is unrelated to the musician of the same name, see ${SITE.domain}/yonyon.`,
		"",
	].join("\n");
}

const YONYON_TITLE = "Yonyon: the software studio behind OrchestKit";
const YONYON_LEAD = `Yonyon is an independent software studio building developer tooling for AI-assisted engineering. It publishes ${SITE.name}, a free, open-source plugin for Claude Code. It is not the musician of the same name.`;

function yonyonMarkdown(): string {
	return [
		`# ${YONYON_TITLE}`,
		"",
		`> ${YONYON_LEAD}`,
		"",
		"## The product",
		"",
		`${SITE.name} bundles ${COUNTS.skills} skills, ${COUNTS.agents} agents, and ${COUNTS.hooks} lifecycle hooks into one MIT-licensed package. Install it inside Claude Code ${SITE.ccVersion} with \`${SITE.installCommand}\`.`,
		"",
		"## Developer resources",
		"",
		`- [Developer resource hub](${SITE.domain}/developers), index of every machine-readable surface ([Markdown](${SITE.domain}/developers.md)).`,
		`- [Documentation](${SITE.domain}/docs) · [llms.txt](${SITE.domain}/llms.txt) · [llms-full.txt](${SITE.domain}/llms-full.txt)`,
		`- [OpenAPI 3.1 spec](${SITE.domain}/openapi.json) · [MCP server](${SITE.domain}/api/mcp) · [/ask (NLWeb)](${SITE.domain}/ask)`,
		`- [API versioning & deprecation policy](${SITE.domain}/api-policy)`,
		"- [Source on GitHub](https://github.com/yonatangross/orchestkit)",
		"",
		"## Frequently asked questions",
		"",
		...YONYON_FAQS.flatMap((f) => [`### ${f.question}`, "", f.answer, ""]),
	].join("\n");
}

const RENDERERS: Record<MarkdownTwinSlug, () => string> = {
	developers: developersMarkdown,
	yonyon: yonyonMarkdown,
};

// Frontmatter for each twin, alongside its renderer so a new slug cannot be
// added with a body but no header block. `canonical` names the HTML page these
// documents are the Markdown representation OF, not their own `.md` URL: the
// two are one resource, and /developers is the one the HTML page declares
// canonical. Title and lead are the SAME constants the body renders, so the
// header and the prose cannot drift apart.
const FRONTMATTER: Record<
	MarkdownTwinSlug,
	{ title: string; description: string; canonical: string }
> = {
	developers: {
		title: DEVELOPERS_TITLE,
		description: DEVELOPERS_LEAD,
		canonical: `${SITE.domain}/developers`,
	},
	yonyon: {
		title: YONYON_TITLE,
		description: YONYON_LEAD,
		canonical: `${SITE.domain}/yonyon`,
	},
};

export function pageMarkdown(slug: MarkdownTwinSlug): string {
	// Wrapped HERE rather than in the route handler, because this is the single
	// choke point every twin passes through. The two surfaces that shipped
	// without a header block were exactly the ones whose rendering path bypassed
	// the route-level wrapping the other five got.
	return withFrontmatter(FRONTMATTER[slug], RENDERERS[slug]());
}
